from collections import deque

def maxRequests(requests, k, window):
    # Group request times by user
    by_user = {}
    for user, t in requests:
        if user not in by_user:
            by_user[user] = []
        by_user[user].append(t)

    kept_total = 0

    for times in by_user.values():
        # Process each user's requests in chronological order
        times.sort()
        kept = deque()   # times of requests we decided to keep, in increasing order

        for t in times:
            # Forget kept requests that fall outside the inclusive window [t - window, t]
            while kept and kept[0] < t - window:
                kept.popleft()
            # Keep this request only if the window still has room
            if len(kept) < k:
                kept.append(t)
                kept_total += 1

    return kept_total
